comp = {"X몰": [10900, 10900, 10900, 8900, 8900], "Y마켓": [10500, 10400, 10500, 10500, 10400]}
ours = [10200, 10200, 10200, 10200, 10200]
for day in range(1, 5):
    for name, p in comp.items():
        drop = (p[day - 1] - p[day]) / p[day - 1] * 100
        if drop >= 10:                      # 하루에 10% 넘게 내리면 행사로 의심
            print(f"{day+1}일째 {name} {p[day-1]}→{p[day]} (-{drop:.1f}%) 행사 의심")
    rank = 1 + sum(p[day] < ours[day] for p in comp.values())
    print(f"{day+1}일째 우리 순위 {rank}/3")

import re
table = {"A 가격 차이": "6.2", "A 전월 대비": "-47.8", "C 가격 차이": "15.2"}
summary = "A는 경쟁사보다 6.2% 비싸고 판매가 전월 대비 -47.8% 줄었다. C는 12.5% 비싸다."  # AI가 쓴 요약이라 치자
known = set(table.values())
for n in re.findall(r"-?\d+(?:\.\d+)?", summary):
    print(n, "확인" if n in known else "원본에 없음 — 사람이 본다")

items = {  # 수요 감소율(%), 하루 조회수, 가격 차이(%)
    "A": (-48, 52000, 6.2), "B": (-12, 41000, 0.0), "C": (-35, 9000, 15.2), "D": (-5, 18000, -3.0)}
def z(vals):                       # 단위가 다른 값을 '평균에서 몇 표준편차'로 맞춘다
    m = sum(vals) / len(vals); s = (sum((v - m) ** 2 for v in vals) / len(vals)) ** 0.5
    return [(v - m) / s for v in vals]
names = list(items)
zd = z([-items[k][0] for k in names]); zv = z([items[k][1] for k in names]); zg = z([items[k][2] for k in names])
score = {k: round(0.5 * zd[i] + 0.3 * zv[i] + 0.2 * zg[i], 2) for i, k in enumerate(names)}
for k, s in sorted(score.items(), key=lambda x: -x[1]): print(k, s)
